CREATE TABLE "teks_standards" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"code" text NOT NULL,
	"subject" text NOT NULL,
	"grade_level" integer NOT NULL,
	"course" text,
	"knowledge_and_skills" text NOT NULL,
	"student_expectation" text NOT NULL,
	"description" text NOT NULL,
	"effective_version" text NOT NULL,
	"source_url" text NOT NULL,
	"search_text" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX "teks_standards_subject_code_version_unique" ON "teks_standards" USING btree ("subject","code","effective_version");--> statement-breakpoint
CREATE INDEX "teks_standards_search_idx" ON "teks_standards" USING gin (to_tsvector('english', "search_text"));
--> statement-breakpoint
